1	<script lang="ts">
2	  import { apiFetch, ApiError } from '../lib/api';
3	  import { sessionStore } from '../stores/session.svelte';
4	  import { chatStore } from '../stores/chat.svelte';
5	  import { dataStore } from '../stores/data.svelte';
6	  import type { ToolCallProposal } from '../stores/chat.svelte';
7	  import MessageList from './MessageList.svelte';
8	  import InputBar from './InputBar.svelte';
9	  import ActionConfirm from './ActionConfirm.svelte';
10	
11	  const sessionHeaders = (): Record<string, string> =>
12	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
13	
14	  /**
15	   * Build session_context from dataStore for the masking pipeline (FR17).
16	   * Sends all non-empty worksheet column values as identifiable fields.
17	   * Field name determines the masking category: fields containing "consultant",
18	   * "client", or "engagement" get typed tokens; others get VALUE_ prefix.
19	   */
20	  function buildSessionContext(): Record<string, string> {
21	    const ctx: Record<string, string> = {};
22	    if (dataStore.worksheetRows.length > 0) {
23	      const firstRow = dataStore.worksheetRows[0];
24	      for (const [key, val] of Object.entries(firstRow)) {
25	        if (val && typeof val === 'string' && val.trim()) {
26	          ctx[key] = val;
27	        }
28	      }
29	    }
30	    return ctx;
31	  }
32	
33	  async function sendMessage(message: string): Promise<void> {
34	    chatStore.clearError();
35	    chatStore.clearPendingAction();
36	    chatStore.addUserMessage(message);
37	    chatStore.chatState = 'loading';
38	
39	    try {
40	      const body = {
41	        message,
42	        history: chatStore.history.slice(0, -1), // all turns before the one just added
43	        session_context: buildSessionContext(),
44	      };
45	
46	      type ChatApiResponse = {
47	        data: { reply: string | null; pending_action: ToolCallProposal | null };
48	        meta: { request_id: string };
49	      };
50	
51	      const response = await apiFetch<ChatApiResponse>('/api/chat', {
52	        method: 'POST',
53	        headers: sessionHeaders(),
54	        body: JSON.stringify(body),
55	      });
56	
57	      // If LLM returned explanatory text alongside the tool call, add it to the chat.
58	      if (response.data.reply) {
59	        chatStore.addAssistantMessage(response.data.reply);
60	      }
61	
62	      if (response.data.pending_action) {
63	        chatStore.setPendingAction(response.data.pending_action);
64	      }
65	
66	      chatStore.chatState = 'idle';
67	    } catch (err) {
68	      const msg =
69	        err instanceof ApiError
70	          ? err.message
71	          : err instanceof Error
72	            ? err.message
73	            : 'Something went wrong. Please try again.';
74	      chatStore.setError(msg);
75	    }
76	  }
77	
78	  async function confirmAction(): Promise<void> {
79	    const action = chatStore.pendingAction;
80	    if (!action) return;
81	
82	    chatStore.clearPendingAction();
83	    chatStore.chatState = 'loading';
84	
85	    try {
86	      type ChatApiResponse = {
87	        data: { reply: string | null; pending_action: ToolCallProposal | null };
88	      };
89	
90	      const response = await apiFetch<ChatApiResponse>('/api/chat', {
91	        method: 'POST',
92	        headers: sessionHeaders(),
93	        body: JSON.stringify({
94	          confirm_action: {
95	            tool_name: action.tool_name,
96	            action: action.action,
97	            params: action.params,
98	          },
99	          history: chatStore.history,
100	          session_context: buildSessionContext(),
101	        }),
102	      });
103	
104	      chatStore.addAssistantMessage(response.data.reply ?? 'Done.');
105	      chatStore.chatState = 'idle';
106	    } catch (err) {
107	      const msg =
108	        err instanceof ApiError
109	          ? err.message
110	          : err instanceof Error
111	            ? err.message
112	            : 'Could not complete the action. Please try again.';
113	      chatStore.setError(msg);
114	    }
115	  }
116	
117	  function cancelAction(): void {
118	    chatStore.clearPendingAction();
119	    chatStore.addAssistantMessage('Action cancelled. How else can I help?');
120	    chatStore.chatState = 'idle';
121	  }
122	</script>
123	
124	<div class="chat-panel">
125	  <h3>Chat</h3>
126	  <div class="chat-body">
127	    <MessageList messages={chatStore.messages} />
128	    {#if chatStore.chatState === 'error'}
129	      <p class="error">{chatStore.chatError}</p>
130	    {/if}
131	    {#if chatStore.pendingAction}
132	      <ActionConfirm
133	        action={chatStore.pendingAction}
134	        onConfirm={confirmAction}
135	        onCancel={cancelAction}
136	      />
137	    {/if}
138	  </div>
139	  <InputBar
140	    onSend={sendMessage}
141	    disabled={chatStore.chatState === 'loading' || chatStore.pendingAction !== null}
142	  />
143	</div>
