1	export interface ChatMessage {
2	  role: 'user' | 'assistant';
3	  content: string;
4	}
5	
6	export interface ToolCallProposal {
7	  tool_name: string;
8	  action: string;
9	  params: Record<string, unknown>;
10	  display_text: string;
11	}
12	
13	type ChatState = 'idle' | 'loading' | 'error';
14	
15	class ChatStore {
16	  messages = $state<ChatMessage[]>([]);
17	  chatState = $state<ChatState>('idle');
18	  chatError = $state<string | null>(null);
19	  pendingAction = $state<ToolCallProposal | null>(null);
20	
21	  get history(): ChatMessage[] {
22	    return this.messages;
23	  }
24	
25	  addUserMessage(content: string): void {
26	    this.messages = [...this.messages, { role: 'user', content }];
27	  }
28	
29	  addAssistantMessage(content: string): void {
30	    this.messages = [...this.messages, { role: 'assistant', content }];
31	  }
32	
33	  setError(msg: string): void {
34	    this.chatError = msg;
35	    this.chatState = 'error';
36	  }
37	
38	  clearError(): void {
39	    this.chatError = null;
40	    if (this.chatState === 'error') this.chatState = 'idle';
41	  }
42	
43	  setPendingAction(action: ToolCallProposal): void {
44	    this.pendingAction = action;
45	  }
46	
47	  clearPendingAction(): void {
48	    this.pendingAction = null;
49	  }
50	}
51	
52	export const chatStore = new ChatStore();
